const C = [];
const add = (id, claim, sources, o = {}) => C.push({ id, claim, sources: sources.map((s) => SOURCES[s]?.url ?? s), sourceIds: sources, status: o.status || 'confirmed', ...(o.date ? { date: o.date } : {}), era: o.era || 'mechanism', ...(o.scope ? { scope: o.scope } : {}), ...(o.book ? { bookClaim: o.book } : {}), ...(o.note ? { note: o.note } : {}) });

// --- History (HI) ---
add('HI01', 'Cloudflare introduced Durable Objects in closed beta on 28 September 2020, in a post by Kenton Varda. Each object has a globally-unique identifier and, in the post\'s words, exists in only one location in the whole world at a time.', ['cf-do-2020'], { date: '2020-09-28', era: '2020 Durable Objects', book: 'c1-closed-beta, c1-one-home' });
add('HI02', 'The 2020 post\'s demonstration is a chat app that uses one Durable Object to control each chat room; users connect over WebSockets and messages from one user are broadcast to the others. It calls the chat room the logical unit of state in a chat app.', ['cf-do-2020'], { date: '2020-09-28', era: '2020 Durable Objects' });
add('HI03', 'The 2020 post presents Durable Objects as a way to coordinate between clients: requests about the same topic are forwarded to the same object, which coordinates between them; independent objects partition an app into logical units.', ['cf-do-2020'], { date: '2020-09-28', era: '2020 Durable Objects', book: 'c1-logical-units' });
add('HI04', 'Inference: one object identity does not mean that every asynchronous operation of its handlers forms one atomic transaction.', ['wd1-actor'], { status: 'inferred', era: '2020 Durable Objects', book: 'c1-interleaving' });
add('HI05', 'On 3 August 2021 Kenton Varda described input gates and output gates: while a storage write is in progress, new outgoing network messages are held back until the write completes; if the write fails, the held messages are discarded and replaced with errors and the object restarts.', ['cf-gates-2021'], { date: '2021-08-03', era: '2021 output gates' });
add('HI06', 'Cloudflare released workerd, the Workers runtime, as open source under the Apache License 2.0 on 27 September 2022 (post by Kenton Varda). The 2026 work is therefore distributed self-hosting progress, not the first open-sourcing.', ['cf-workerd-2022'], { date: '2022-09-27', era: '2022 workerd', book: 'c1-already-open' });
add('HI07', 'The 2022 workerd post says workerd is not, on its own, a secure way to run possibly-malicious code; it must be enclosed in an additional sandboxing layer.', ['cf-workerd-2022'], { date: '2022-09-27', era: '2022 workerd' });
add('HI08', 'On 26 September 2024 Cloudflare put SQLite inside Durable Objects, running in the very same thread as the application; Kenton Varda wrote that latency is effectively zero because there is no communication barrier between application and SQLite. This describes local access, not end-to-end durable acknowledgement.', ['cf-sqlite-2024'], { date: '2024-09-26', era: '2024 SQLite', book: 'c1-sqlite-local, c4-local-sqlite' });
add('HI09', 'Cloudflare\'s hosted Storage Relay Service (SRS) monitors changes to SQLite\'s write-ahead log by hooking SQLite\'s VFS, and uploads them to object storage in batches of up to 10 seconds or 16 MB, whichever comes first.', ['cf-sqlite-2024'], { date: '2024-09-26', era: '2024 SQLite', scope: 'cloudflare-hosted' });
add('HI10', 'SRS forwards each committed change log immediately to five follower machines, each in a different physical data center; once at least three respond that they received it, SRS tells the application the write is confirmed, which opens the output gate.', ['cf-sqlite-2024'], { date: '2024-09-26', era: '2024 SQLite', scope: 'cloudflare-hosted' });
add('HI11', 'The 2024 post describes object storage latency as relatively high, measured in tens or hundreds of milliseconds, and says the application cannot wait ten seconds to confirm a write.', ['cf-sqlite-2024'], { date: '2024-09-26', era: '2024 SQLite', scope: 'cloudflare-hosted' });
add('HI12', 'In the 9 October 2026 joint post, Ryan Dahl wrote that workerd\'s Durable Objects support is limited to a single instance; Kenton Varda wrote that workerd has always had one big gap in its production-readiness, Durable Objects, which it implements only in a single-instance way, good enough for local testing but unable to scale.', ['cf-deno-2026'], { date: '2026-10-09', era: '2026 joining', book: 'c1-single-instance-gap', note: 'Verified section authorship 2026-10-31: the single-instance sentence (Q07) is in Ryan Dahl\'s section; the one-big-gap passage (Q26) in Kenton Varda\'s.' });
add('HI13', 'In the joint post Ryan Dahl writes that this is why he started celld, wanting one binary, written in Rust, with object storage as its only external service dependency.', ['cf-deno-2026'], { date: '2026-10-09', era: '2026 celld' });
add('HI14', 'In the joint post Kenton Varda writes that the Deno team released celld in August 2026 and that Cloudflare was delighted. The exact August day is not established from a primary source; the film uses the month only.', ['cf-deno-2026'], { date: '2026-08', era: '2026 celld' });
add('HI15', 'On 9 October 2026 Deno (post by Ryan Dahl) and Cloudflare announced that the entire Deno team is joining Cloudflare.', ['deno-2026', 'cf-deno-2026'], { date: '2026-10-09', era: '2026 joining', book: 'c1-team-direction' });
add('HI16', 'Announced plans, as stated by Deno on 9 October 2026: the Deno runtime is supported for another year with monthly bug-fix and security releases, after which Deno ends its development of the runtime; Deno Deploy continues for six months before shutting down, with migration support for paying customers; JSR continues with its infrastructure moving to Cloudflare; rusty_v8 continues to be supported with work toward integrating it into workerd; Deno remains open source.', ['deno-2026'], { date: '2026-10-09', era: '2026 joining', book: 'c1-transition-plan, c1-continuing-projects', note: 'Announced intentions, not perpetual guarantees.' });
add('HI17', 'Neither announcement states a purchase price or deal terms; the Cloudflare post carries an "Acquisitions" tag. The film does not describe terms.', ['cf-deno-2026', 'deno-2026'], { date: '2026-10-09', era: '2026 joining' });
add('HI18', 'The joint post says Ryan Dahl and Bert Belder will lead a new effort to make workerd self-hosting a first-class supported way to build and run apps, which will involve merging code and ideas from celld back into workerd.', ['cf-deno-2026'], { date: '2026-10-09', era: '2026 joining', book: 'c6-announced-direction' });
add('HI19', 'Ryan Dahl writes that the team will put its future development into this shared platform rather than continuing a separate runtime.', ['deno-2026'], { date: '2026-10-09', era: '2026 joining' });
add('HI20', 'The supplied workerd commit, "Cluster workerd processes over a shared bucket (#7994)", is authored by Ryan Dahl at 2026-10-28 20:11:42 -07:00 (29 October 03:11 UTC). Its message calls it the beginning of merging celld\'s functionality into workerd.', ['wd-commit'], { date: '2026-10-29', era: '2026 the commit', book: 'c1-initial-cluster' });
add('HI21', 'The commit message: several workerd processes form a cluster by sharing one S3-compatible bucket (Config.cluster, behind --experimental); each Durable Object has one owner at a time; requests reach it from any process; when its owner dies another process picks it up from the bucket; objects use the bucket as cold storage; for now a write is acknowledged only once fully synced to the bucket; alarms are not supported yet.', ['wd-commit', 'wd0-capnp'], { date: '2026-10-29', era: '2026 the commit', scope: 'workerd-initial' });
add('HI22', 'Alarms for clustered Durable Objects landed in workerd on 30 October 2026 (#8090) and facets on 31 October 2026 (#8113), both authored by Ryan Dahl; the later snapshot ad78a8fe includes alarm tests.', ['wd-alarms-commit', 'wd-facets-commit', 'wd1-alarms', 'wd1-test'], { date: '2026-10-31', era: '2026 the commit', scope: 'workerd-later', book: 'c1-later-features' });
add('HI23', 'celld describes itself as self-hosted, distributed Durable Objects: an open-source daemon that runs a Workers application from its wrangler.json on your own machines, keeping long-term state in an S3-compatible, Google Cloud Storage or Azure Blob bucket. Its README says it needs no serving control plane or consensus service, and that the fleet needs no membership protocol, failure detector, or consensus service.', ['cd-readme'], { era: '2026 celld', scope: 'celld-0.6.3', book: 'c1-celld-model' });
add('HI24', 'In celld a KV namespace, a queue, a D1 database and a Workflow are each a cell, with the same lease, replication and failover as a Durable Object.', ['cd-readme'], { era: '2026 celld', scope: 'celld-0.6.3' });
add('HI25', 'celld\'s SQLite-to-object-store replicator crate was vendored on 2026-08-03 from rustyriver, a Rust reimplementation of Litestream v0.5 (github.com/benbjohnson/litestream) and the LTX format (github.com/superfly/ltx), all Apache-2.0.', ['cd-ltx'], { date: '2026-08-03', era: '2026 celld', scope: 'celld-0.6.3' });
add('HI26', 'The pinned celld snapshot 8702f6d is version 0.6.3, dated 2026-10-21; the celld website may show a different current version.', ['cd-tag', 'celld-site'], { date: '2026-10-21', era: '2026 celld', scope: 'celld-0.6.3' });
add('HI27', 'Sequence: Durable Objects debuted in 2020, workerd became open source in 2022, SQLite in Durable Objects arrived in 2024, celld was released in August 2026, the Deno team joining Cloudflare was announced on 9 October 2026, and the supplied clustering commit landed on 28 October 2026 (Pacific).', ['cf-do-2020', 'cf-workerd-2022', 'cf-sqlite-2024', 'cf-deno-2026', 'wd-commit'], { era: 'chronology', book: 'c6-historical-sequence' });

// --- The bucket (SB) ---
add('SB01', 'On 1 December 2020 AWS announced that Amazon S3 delivers strong read-after-write consistency automatically for all applications: after a write or overwrite, the next read returns the latest version, and listings reflect changes.', ['aws-sc-2020'], { date: '2020-12-01', era: 'the bucket', scope: 's3' });
add('SB02', 'Werner Vogels explained that S3\'s earlier eventual consistency arose because writes might flow through one part of the cache infrastructure while reads queried another.', ['vogels-2021'], { date: '2021-04-20', era: 'the bucket', scope: 's3' });
add('SB03', 'Vogels describes how S3 built strong consistency internally: a cache coherence protocol for its metadata caches, new replication logic that lets S3 reason about the order of operations per object, and a witness component notified every time an object changes, which acts like a read barrier so a cache learns whether its view is stale.', ['vogels-2021'], { date: '2021-04-20', era: 'the bucket', scope: 's3' });
add('SB04', 'Vogels writes that S3 verified the design with integration tests, deductive proofs of the cache coherence algorithm and model checking, later extended to runnable code, and that this verification was more work than the implementation itself.', ['vogels-2021'], { date: '2021-04-20', era: 'the bucket', scope: 's3' });
add('SB05', 'On 20 August 2024 AWS announced S3 conditional writes with If-None-Match: a write that succeeds only if no object exists at that key; AWS said customers no longer need to build client-side consensus mechanisms to coordinate such updates. When several conditional creates race on one key, one succeeds and the others fail with a precondition error.', ['aws-cw-2024-08', 'aws-cw-docs'], { date: '2024-08-20', era: 'the bucket', scope: 's3', book: 'c2-conditional-create' });
add('SB06', 'On 25 November 2024 AWS added If-Match conditional writes: S3 checks that the object\'s ETag still matches the value in the request before committing an overwrite, letting workloads offload compare-and-swap operations to S3.', ['aws-cw-2024-11', 'aws-cw-docs'], { date: '2024-11-25', era: 'the bucket', scope: 's3', book: 'c2-conditional-overwrite' });
add('SB07', 'A conditional write is applied only if the storage-side precondition holds for that write; the condition is checked by the store, not by the client.', ['aws-cw-docs'], { era: 'the bucket', scope: 's3', book: 'c2-atomic-condition, c2-read-write-gap' });
add('SB08', 'Inference: with a separate read and an unconditional write, two contenders can both observe the key absent and both write; the last overwrite wins the key but cannot retract the serving decisions the other already made.', ['aws-cw-docs', 'wd0-ownership'], { status: 'inferred', era: 'the bucket', book: 'c2-naive-race, c2-overwrite-is-not-authority' });
add('SB09', 'celld\'s guarantees require a bucket that provides a conditional create, a conditional overwrite, read-after-write consistency and ranged reads (list-after-write consistency only for optional epoch GC), plus a supervisor that restarts the process.', ['cd-guarantees'], { era: 'the bucket', scope: 'celld-0.6.3', book: 'c2-fresh-read' });
add('SB10', 'At v0.6.3 celld lists Amazon S3, Cloudflare R2, Tigris, Google Cloud Storage and Azure Blob Storage as qualified stores; its release tests run against R2.', ['cd-guarantees'], { era: 'the bucket', scope: 'celld-0.6.3' });
add('SB11', 'celld\'s documentation warns that some S3-compatible stores do not implement the required conditional writes, so two nodes can own one cell on them, and that a store which accepts the conditional headers but ignores the condition fails late and silently.', ['cd-guarantees'], { era: 'the bucket', scope: 'celld-0.6.3', book: 'c6-conditions-required' });
add('SB12', 'celld\'s storage test sends four conditional writes (create, reject-create, update, reject-stale); two of the four must fail. Every node runs the same writes plus a ranged-read check before it serves, and cannot disable the test.', ['cd-guarantees'], { era: 'the bucket', scope: 'celld-0.6.3', book: 'c2-probe-semantics' });
add('SB13', 'Inference: serialising one ownership key does not by itself give atomic application transactions across separate objects.', ['wd0-ownership', 'aws-cw-docs'], { status: 'inferred', era: 'the bucket', book: 'c2-one-key-scope' });
add('SB14', 'Inference: the application fleet relies on the store\'s conditional serialisation instead of running its own consensus service for ownership; the coordination still exists, inside the storage service (SB03, SB04).', ['cd-readme', 'wd0-ownership', 'vogels-2021'], { status: 'inferred', era: 'the bucket', book: 'c2-outsource-primitive' });
add('SB15', 'Inference: moving ownership serialisation into the bucket makes ownership progress depend on the bucket\'s semantics and availability.', ['wd0-ownership', 'cd-guarantees'], { status: 'inferred', era: 'the bucket', book: 'c2-referee-dependence' });
add('SB16', 'workerd guards replacement of an ownership record with an opaque version (Guard::Match) or requires absence (Guard::Absent); here the ETag-like version is an opaque guard, not a content checksum.', ['wd1-bucket', 'wd0-ownership'], { era: 'the bucket', scope: 'workerd-initial', book: 'c2-version-guard' });
add('SB17', 'celld uses Cloud Storage\'s own generation-match header for gs:// buckets because Cloud Storage does not apply If-Match to a PUT: the same promise is spelled differently by different stores.', ['cd-guarantees'], { era: 'the bucket', scope: 'celld-0.6.3' });

// --- Ownership (OW) ---
add('OW01', 'In workerd each Durable Object has one owner record, do/<namespace>/<actor>/own.json, described in the code as the only authority for who owns it and whose log holds its latest commits. It holds three fields: node, epoch and from.', ['wd0-ownership'], { scope: 'workerd-initial', book: 'c2-record-fields' });
add('OW02', 'In workerd, from is the last epoch that opened. A claim writes the next epoch and copies from unchanged; the opening write sets from equal to the epoch. An epoch is still recovering while from differs from epoch, and it recovers from\'s log.', ['wd0-ownership'], { scope: 'workerd-initial', book: 'c3-recover-from' });
add('OW03', 'In workerd a claimant that dies mid-recovery leaves from unchanged, so the next claimant still recovers the last epoch that actually opened.', ['wd0-ownership'], { scope: 'workerd-initial', book: 'c3-recover-from' });
add('OW04', 'workerd\'s acquire_or_route: a record with no owner, or naming an instance whose lease expired, is taken over with the next epoch by a conditional write, so exactly one claimant wins; a record naming a live peer sends the request to that peer instead.', ['wd0-ownership', 'wd0-registry'], { scope: 'workerd-initial', book: 'c2-one-record, c3-successor-epoch' });
add('OW05', 'For a brand-new object, workerd creates own.json already opened in one conditional create; the claimant that loses that write routes to the winner.', ['wd0-owner', 'wd0-ownership'], { scope: 'workerd-initial' });
add('OW06', 'workerd retries a contended claim up to 8 times and refreshes a route at most every 5 seconds; a route is a cached optimisation, not proof of ownership.', ['wd0-ownership'], { scope: 'workerd-initial' });
add('OW07', 'workerd opens a claimed epoch only if the record still names this node at this epoch and from has not yet been set to it; the guarded write sets from to the epoch. If the record changed, the epoch never opens.', ['wd0-ownership'], { scope: 'workerd-initial', book: 'c5-open-after-restore' });
add('OW08', 'On takeover workerd deletes the node\'s non-authoritative local database, restores the recovering epoch\'s session from the bucket, uploads the starting snapshot of the new session, and only then performs the conditional open; if the record was superseded first, the epoch fails with "superseded before it opened".', ['wd0-owner'], { scope: 'workerd-initial', book: 'c4-bucket-recoverable, c5-takeover-base, c5-open-after-restore' });
add('OW09', 'Inference from owner.rs: an object serves commits only after its epoch has opened, so a claimed epoch that never opened acknowledged nothing.', ['wd0-owner'], { status: 'inferred', scope: 'workerd-initial' });
add('OW10', 'In celld each cell has one ownership record, cells/<cell>/own.json, naming the owner node\'s session and a fencing epoch; it is acquired by conditional create or compare-and-swap, every activation advances the epoch so an epoch never has two writers, and celld never deletes the record.', ['cd-guarantees', 'cd-ownership'], { scope: 'celld-0.6.3' });
add('OW11', 'celld writes each cell\'s SQLite data under cells/<cell>/ltx/e<epoch>/ with unconditional PUTs; the epoch in the key is the fence: a node that lost ownership can keep writing, but only into a superseded prefix, and a restore selects the current lineage.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('OW12', 'If celld finds data under a cell\'s ltx prefix but no ownership record, it refuses to acquire the cell, because a new record at epoch 1 would start it with an empty database.', ['cd-guarantees'], { scope: 'celld-0.6.3' });

// --- Leases (LE) ---
add('LE01', 'workerd lease constants: lease 20,000 ms; renewal every 3,000 ms, each bounded at 4,000 ms; a failed renewal retried every 1,000 ms; maximum clock skew 2,000 ms; safety margin twice the skew, 4,000 ms.', ['wd0-lease'], { scope: 'workerd-initial', book: 'c3-lease-constants, c3-safety-margin' });
add('LE02', 'A comment in workerd\'s lease code records that R2 stalls writes about 5.5 s at every 5-minute mark and that a 2 s renewal bound cancelled them and fenced every node, which is why each renewal is bounded at 4 s.', ['wd0-lease'], { scope: 'workerd-initial' });
add('LE03', 'In workerd a lease holds at time now only if now plus the 4,000 ms safety margin is before its expiry; an actor serves only while it holds.', ['wd0-lease'], { scope: 'workerd-initial' });
add('LE04', 'Before each renewal workerd fences if the node\'s clock is more than 2,000 ms off the bucket\'s, or if the lease would not still hold 4,000 ms from now (a paused process or blocked loop may have been taken over and must not renew and serve on).', ['wd0-lease'], { scope: 'workerd-initial', book: 'c3-skew-check, c3-paused-node' });
add('LE05', 'After a failed renewal workerd retries while the lease still covers the renewal timeout and fences otherwise, so the node is gone before a peer may take over.', ['wd0-lease'], { scope: 'workerd-initial', book: 'c3-bounded-wait' });
add('LE06', 'In workerd, fence means stop serving: the process exits before peers may take over.', ['wd0-lease'], { scope: 'workerd-initial' });
add('LE07', 'Inference from holds and before_renew: with an expiry at 20,000 ms, the node may serve only while its clock reads below 16,000 ms and may start a renewal only below 12,000 ms. These are arithmetic boundaries, not guaranteed timer delivery.', ['wd0-lease'], { status: 'inferred', scope: 'workerd-initial', book: 'c3-strict-boundaries' });
add('LE08', 'workerd measures each node\'s skew against the bucket\'s observed clock; when no observation is available the skew defaults to zero, so the bound is an assumption rather than verified synchronisation.', ['wd1-cluster', 'wd1-bucket'], { scope: 'workerd-later', book: 'c3-clock-observation' });
add('LE09', 'Inference: an expired lease does not prove a machine died; the node may be paused. Safety rests on the old owner fencing itself before expiry and on the post-upload epoch check, not on knowing who is alive.', ['wd0-lease', 'wd0-owner', 'cd-guarantees'], { status: 'inferred' });
add('LE10', 'workerd node records carry an expiry that peers use to decide whether a node is live; the lease code calls a peer whose record was not renewed for a full lease dead, as a working rule.', ['wd0-registry', 'wd0-lease'], { scope: 'workerd-initial', book: 'c3-node-expiry' });
add('LE11', 'celld leases default to a 10,000 ms lifetime renewed after one third of it; when the published expiry passes the node fences itself, stopping each active cell and failing incomplete requests, writes nothing, and exits with code 3; celld also checks the published expiry on every routed request.', ['cd-guarantees'], { scope: 'celld-0.6.3', note: 'Do not substitute workerd\'s 20 s / 2 s-skew arithmetic into celld.' });
add('LE12', 'celld\'s acknowledgement check after a bucket proof reads the ownership record instead of a clock, so a paused process or a skewed clock cannot pass it.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('LE13', 'Inference: when the bucket is unreachable, no new upload-backed acknowledgements can complete, and sustained renewal failure fences the affected writers: safety is kept by stopping, not by serving on.', ['wd0-lease', 'wd0-owner'], { status: 'inferred', book: 'c3-outage-stop, c6-bucket-partition' });

// --- WAL capture (WA) ---
add('WA01', 'SQLite\'s write-ahead log begins with a 32-byte header; each frame is a 24-byte frame header followed by one page; in a commit frame the header records the size of the database in pages after the commit, and is zero in other frames.', ['sqlite-wal-format', 'wd0-capture'], { scope: 'general', book: 'c4-commit-marker' });
add('WA02', 'workerd\'s capture reads the writes SQLite makes to its WAL, as workerd\'s VFS reports them, and cuts them into transactions: frames since the last commit are buffered, and the write that completes a commit frame completes one transaction.', ['wd0-capture'], { scope: 'workerd-initial', book: 'c4-write-ahead-pages, c4-unfinished-frames' });
add('WA03', 'In workerd\'s capture a write at offset 0 starts a new WAL after a checkpoint copied earlier frames into the database file, and a rolled-back transaction\'s frames are overwritten by the next transaction\'s.', ['wd0-capture'], { scope: 'workerd-initial', book: 'c4-unfinished-frames' });
add('WA04', 'workerd stores each object\'s log in the bucket as gzipped files: batches log/<session>/<end> with runs of page frames merged to the newest version of each page, and snapshots snapshot/<session>/<frame>, in its own frames.capnp format.', ['wd0-log'], { scope: 'workerd-initial', book: 'c4-merged-batches' });
add('WA05', 'Every workerd log file is gzipped; gzip ends with the content\'s CRC-32 and length, which the decoder checks, so a corrupt or truncated copy fails to replay rather than replaying wrong or short.', ['wd0-log'], { scope: 'workerd-initial', book: 'c5-checksum-boundary' });
add('WA06', 'celld captures SQLite WAL changes into the LTX format (transaction ranges and page checksums); workerd\'s cluster path uses frames.capnp instead. The two implementations are distinct.', ['cd-ltx', 'wd0-log'], { scope: 'celld-0.6.3', book: 'c4-different-ltx' });
add('WA07', 'In workerd each epoch writes its own session of the object\'s log, starting with a snapshot of the state it inherited.', ['wd0-owner'], { scope: 'workerd-initial' });
add('WA08', 'workerd snapshots a session when the log since the last snapshot has reached the database\'s size, keeping bucket writes within about twice the log, and uploads a replacement snapshot before deleting the files it covers.', ['wd0-owner'], { scope: 'workerd-initial', book: 'c5-snapshot-before-delete' });
add('WA09', 'In the later workerd snapshot, facets add further lanes to the captured log under the same session and sequence.', ['wd1-capture'], { scope: 'workerd-later' });

// --- Durability / acknowledgement (DU) ---
add('DU01', 'workerd: a commit is acknowledged once the bucket holds it and own.json still names the epoch after the upload.', ['wd0-owner', 'wd1-owner'], { scope: 'workerd-initial', book: 'c4-gate-order, c4-upload-then-epoch' });
add('DU02', 'workerd\'s push stages the captured frames, uploads them, rereads the current epoch from own.json, and if it no longer matches returns "epoch was superseded" without acknowledging; only a match advances the acknowledgement.', ['wd0-owner', 'wd0-ownership'], { scope: 'workerd-initial', book: 'c3-post-upload-fence' });
add('DU03', 'workerd uploads commits as a group: each caller captures its own transactions, then one at a time a caller uploads everything captured so far on behalf of all, so a hot object pays one upload per group; each caller returns once the acknowledgement covers its own target.', ['wd0-owner'], { scope: 'workerd-initial', book: 'c4-group-coverage' });
add('DU04', 'workerd\'s code describes the epoch reread as "the re-read after a bucket upload that makes the upload an acknowledgement".', ['wd0-ownership'], { scope: 'workerd-initial' });
add('DU05', 'In workerd cluster mode local SQLite completion is not the acknowledgement: the commit waits for bucket-backed coverage. At both inspected workerd snapshots the commit path acknowledges after the upload and epoch reread; no follower acknowledgement path is present.', ['wd0-owner', 'wd1-owner'], { scope: 'workerd-initial', book: 'c4-local-not-proof' });
add('DU06', 'celld holds each response until a durability proof covers every write it can reveal: write responses, read-only responses when an uncovered committed write exists, error responses, R2 mutations, raw TCP actions, and each chunk of a streamed body.', ['cd-guarantees', 'cd-gate'], { scope: 'celld-0.6.3', book: 'c4-observations-gated, c4-readonly-error' });
add('DU07', 'celld rejects output while an SQL write cursor is unfinished; outside an explicit transaction the application must consume its rows before output.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('DU08', 'Inference, stated in celld\'s own words as "a missing acknowledgement does not prove a write absent": a lost reply cannot tell a client that a write did not happen, so durability alone does not give exactly-once effects on retry.', ['cd-guarantees'], { status: 'inferred', book: 'c4-reply-uncertainty' });
add('DU09', 'Inference: local SQL work and the remote upload plus authority check are separate parts of a workerd acknowledgement\'s latency; any widths drawn are illustrative, not measured.', ['cf-sqlite-2024', 'wd0-owner'], { status: 'inferred', book: 'c6-latency-path' });
add('DU10', 'Inference: lease expiry, guarded ownership updates and the post-upload epoch check close different failure windows; none of them alone suffices.', ['wd0-lease', 'wd0-ownership', 'wd0-owner'], { status: 'inferred', book: 'c3-distinct-jobs' });
add('DU11', 'A superseded workerd owner still uploading can finish writing files into its old session; that does not make it the owner, and the next epoch deletes those leftovers.', ['wd0-owner'], { scope: 'workerd-initial', book: 'c3-obsolete-upload' });

// --- Recovery (RE) ---
add('RE01', 'workerd restores a session from its newest snapshot, then each batch past it, skipping frames a batch before already applied by their sequence.', ['wd0-log'], { scope: 'workerd-initial', book: 'c5-snapshot-replay, c5-sequence-coverage' });
add('RE02', 'workerd replay fails if a skipped batch\'s frames were never replayed: a batch in between is missing, and the restore refuses rather than continuing.', ['wd0-log'], { scope: 'workerd-initial', book: 'c5-reject-gaps' });
add('RE03', 'Inference: checksums detect corrupt or truncated bytes; they cannot recreate missing ones.', ['wd0-log'], { status: 'inferred', book: 'c5-checksum-boundary' });
add('RE04', 'Restore replays recorded pages; it does not re-run application handlers.', ['wd0-log'], { scope: 'workerd-initial', book: 'c5-snapshot-replay' });
add('RE05', 'Inference from ownership.rs: if A opened epoch 7 (record A, 7, from 7), and B claims 8 (B, 8, from 7) but dies before opening, C\'s claim writes (C, 9, from 7) and recovers epoch 7\'s log; had B opened 8 (B, 8, from 8), C would recover 8.', ['wd0-ownership', 'wd0-owner'], { status: 'inferred', scope: 'workerd-initial', note: 'Hosts and epoch numbers are illustrative (FX01).' });
add('RE06', 'Inference from owner.rs: an old owner that wakes after a successor has claimed can still upload into its old session, but its reread shows the newer epoch, so it never acknowledges.', ['wd0-owner', 'wd0-ownership'], { status: 'inferred', scope: 'workerd-initial', book: 'c3-post-upload-fence' });

// --- celld fleet (CE) ---
add('CE01', 'celld\'s default durability is fleet mode: the owner sends each write to one or two other nodes, its followers, and every follower must fsync it; celld can acknowledge such a write before its bucket upload completes, and uploads afterwards.', ['cd-guarantees', 'cd-readme'], { scope: 'celld-0.6.3', book: 'c5-fleet-default, c5-follower-proof' });
add('CE02', 'A celld node never counts itself as a follower and one follower is enough, so a fleet needs two running nodes before any fleet proof; a one-node fleet requests the fleet posture and does not get it.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('CE03', 'A celld node recruits up to two followers, so a fleet of three or more holds three copies of an acknowledged write; until a second follower is recruited, a write not yet in the bucket is only on the owner and one follower.', ['cd-guarantees'], { scope: 'celld-0.6.3', book: 'c5-bucket-fallback' });
add('CE04', 'A celld node without an ensemble stays correct by acknowledging on a bucket proof instead, at the cost of latency: an object store round trip is much slower than a follower fsync.', ['cd-guarantees'], { scope: 'celld-0.6.3', book: 'c5-bucket-fallback, c6-fleet-tradeoff' });
add('CE05', 'Because fleet acknowledgements can precede the bucket, each celld process session creates a conditional node-log record before its first fleet-durable acknowledgement.', ['cd-guarantees', 'cd-nodelog'], { scope: 'celld-0.6.3' });
add('CE06', 'A celld cold activation checks the prior owner\'s node-log record before reading the bucket: absent proves the session never acknowledged past the bucket; sealed proves recovery completed; open or recovering forces recovery first: compare-and-swap the record to fence it, seal the reachable followers, upload their retained data into the cell\'s prefixes, and mark the record sealed.', ['cd-guarantees', 'cd-nodelog'], { scope: 'celld-0.6.3', book: 'c5-tail-obligation, c5-seal-before-restore' });
add('CE07', 'celld: a takeover seals the prior node-log session before it restores, so a stale owner cannot complete another fleet proof.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('CE08', 'celld: once the log epoch is active, at least one current follower must return its complete retained range, or the activation fails and keeps the recovery requirement.', ['cd-guarantees'], { scope: 'celld-0.6.3', book: 'c5-cannot-certify' });
add('CE09', 'celld documents recovery limits: a follower\'s HTTP error does not prove its data absent, so persistent errors can block recovery; a range with a damaged batch or gap cannot be certified until valid data covers it; an older node\'s entries-only tail proves neither completeness nor loss; a deleted final batch is undetectable if nothing later records its range.', ['cd-guarantees'], { scope: 'celld-0.6.3', book: 'c5-cannot-certify' });
add('CE10', 'A restarting celld node serves follower seal and tail requests before its own predecessor recovery completes, so nodes that restart together can recover acknowledged writes from surviving follower disks.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('CE11', 'celld recovery of a large dead node can take minutes; failed attempts retry with a backoff (default 1,000 ms) and waiting requests fail only after 240 attempts by default.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('CE12', 'celld restores by chaining epoch prefixes from the newest down to an epoch that opened with a whole-database snapshot; a predecessor that does not end exactly at the successor\'s cut is not part of the chain.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('CE13', 'Inference (the mandatory distinction): celld\'s epoch prefixes fence bucket writes, but they cannot recover a tail that was acknowledged on followers only; the sealing recovery gate is what recovers it. workerd\'s bucket proofs and celld\'s follower proofs need different recovery paths because they acknowledge bytes in different places.', ['cd-guarantees', 'wd0-owner'], { status: 'inferred', scope: 'celld-0.6.3', book: 'c5-distinct-proofs' });
add('CE14', 'celld\'s guarantees open with two promises: exactly one node serves a cell at a time, and celld does not acknowledge a write until it survives a failure; both require a bucket with working conditional writes and ranged reads and a supervisor that restarts the process.', ['cd-guarantees'], { scope: 'celld-0.6.3' });

// --- Limits and now (LI) ---
add('LI01', 'At the supplied commit workerd clustering is experimental (Config.cluster behind --experimental) and lacks alarms; it is a beginning, not full platform parity.', ['wd-commit', 'wd0-capnp'], { scope: 'workerd-initial', book: 'c6-announced-direction' });
add('LI02', 'The workerd cluster integration test starts a fake S3 and several workerd instances and exercises consistent state across instances (single-writer correctness), forwarding from the wrong instance, takeover after a node is killed and per-instance lease records; the later snapshot adds alarms on a survivor and facets. This film inspected these tests and did not execute them.', ['wd0-test', 'wd1-test'], { scope: 'workerd-later', book: 'c6-tested-alarm' });
add('LI03', 'Inference: the alarm tests assert observed firings in specific kill-and-recover scenarios; they do not establish exactly-once external effects for arbitrary applications.', ['wd1-test'], { status: 'inferred', scope: 'workerd-later', book: 'c6-alarm-test-scope' });
add('LI04', 'celld must run under a supervisor that restarts it without an attempt limit and waits at least one lease lifetime between attempts; a fenced node exits and the fleet loses that capacity until restart.', ['cd-guarantees'], { scope: 'celld-0.6.3' });
add('LI05', 'celld reserves bucket prefixes it reads to fence and restore cells; an operator must not delete, expire or overwrite objects there, so bucket lifecycle rules must not select them.', ['cd-guarantees'], { scope: 'celld-0.6.3', book: 'c6-preserve-records' });
add('LI06', 'celld documents its supported APIs and limitations; running the runtime yourself does not establish full parity with the hosted platform.', ['cd-compat', 'cf-deno-2026'], { scope: 'celld-0.6.3', book: 'c6-parity-scope' });
add('LI07', 'Inference: what becomes portable is the runtime\'s recovery machinery together with a qualified storage contract; either alone is not enough.', ['cf-deno-2026', 'wd0-owner', 'cd-guarantees'], { status: 'inferred', book: 'c6-portable-recovery, c6-composed-contract' });
add('LI08', 'workerd is intended for self-hosted application execution, and celld runs SQLite-backed cells on operator-owned nodes.', ['cd-readme', 'cf-workerd-2022'], { book: 'c6-owned-compute' });

// --- Fixtures (FX) ---
add('FX01', 'Illustrative teaching fixtures: the chat room (\"the harbour room\"), the message (#42, \"the ferry is late\"), the houses A, B and C, the epochs 7, 8 and 9, the times on lease plates and the page numbers on the ribbon are invented for teaching and labelled as such on screen or in narration. No measured latency, benchmark or real deployment is depicted.', ['wd0-ownership'], { status: 'illustrative', era: 'fixture' });

