const quotes = Q.map(([id, text, speaker, date, src, context]) => ({ id, text, speaker, date, source: SOURCES[src].url, sourceId: src, context, verified: '2026-10-31 verbatim against the fetched page / pinned file' }));

const sources = { $notes: 'Pinned primary sources for the durable-objects-unbound film, verified 2026-10-31. Code pins: workerd supplied commit ' + W0 + ' (initial, experimental, no alarms); workerd later snapshot ' + W1 + ' (alarms ' + WA + ', facets); celld ' + C0 + ' (v0.6.3). Repository files were read at these pins; upstream test suites were inspected, not executed.', pins: { workerdInitial: W0, workerdLater: W1, workerdAlarms: WA, celld: C0 }, sources: Object.entries(SOURCES).map(([id, s]) => ({ id, ...s })) };

writeFileSync(path.join(RES, 'sources.json'), JSON.stringify(sources, null, 1) + '\n');
writeFileSync(path.join(RES, 'claims.json'), JSON.stringify(C, null, 1) + '\n');
